diff --git a/tests/member-free-days-paid.test.ts b/tests/member-free-days-paid.test.ts
new file mode 100644
index 000000000..b3c8defe8
--- /dev/null
+++ b/tests/member-free-days-paid.test.ts
@@ -0,0 +1,182 @@
+/**
+ * 641 [WG1], second look (Claude 4 team review of #2912, A1, M1 and M2; fixed
+ * by Claude 4 on Claude 5's behalf). Free days are given with Stripe's
+ * trial_end, so Stripe answers the membership "trialing" while they run and
+ * keeps that trial_end on it after. A member who PAID and was given free days
+ * is still a paying member: every reader that takes "trialing" or trial_end
+ * for a free trial must read it as paid. Checked, on what giving free days
+ * really leaves on the subscription (Stripe faked through fetch, metadata
+ * merged the way Stripe merges it):
+ *
+ *   - membership numbers and MRR keep the member paying and their paid
+ *     history whole, while the days run and after they end, and never count
+ *     the days as a trial, nor as a trial that converted;
+ *   - an earlier real trial on that membership is still counted as one;
+ *   - free days given inside a real trial leave it a trial (it was never paid);
+ *   - the yearly offer is not made while paid free days run, and the email
+ *     that offers it counts the payments from the real start;
+ *   - an answer from Stripe out of shape, or with more than one page, is "not
+ *     known", never "no running membership" (rule 24).
+ *
+ * Synthetic data only; no request leaves the process.
+ */
+import { claimHandle, ensureStatsId, ensureStoreId, setStripeAccount, storeForEmail } from "@/lib/store";
+import { freeDaysSubs, giveFreeDays } from "@/lib/member-free-days";
+import { numbersFrom, readSub } from "@/lib/membership-numbers";
+import { movementsFrom } from "@/lib/mrr-movements";
+import { askFits, yearlyChoice } from "@/lib/yearly-switch-rules";
+import { store as redis } from "./redis-stub";
+import { done, is, part } from "./check";
+
+process.env.STRIPE_SECRET_KEY = "sk_test_member_free_days_paid_only";
+process.env.RESEND_API_KEY = "re_test_a_stand_in_key_for_tests_only";
+
+const DAY = 86_400;
+const NOW = Math.floor(Date.now() / 1000);
+const PERIOD_END = NOW + 20 * DAY;
+const TRIAL_END = NOW + 5 * DAY;
+const HANDLES = new Set(["paiddays"]);
+
+type Sub = Record<string, unknown> & { id: string; metadata: Record<string, string> };
+const subscription = (id: string, extra: Record<string, unknown> = {}): Sub => ({
+  id,
+  status: "active",
+  currency: "usd",
+  customer: "cus_member0001",
+  start_date: NOW - 200 * DAY,
+  trial_end: null,
+  metadata: { store: "paiddays", product: "prod000001" },
+  items: { data: [{ quantity: 1, current_period_end: PERIOD_END, price: { unit_amount: 2900, currency: "usd", recurring: { interval: "month", interval_count: 1 } } }] },
+  ...extra,
+}) as Sub;
+
+let subs: Sub[] = [];
+type Mode = "healthy" | "customers out of shape" | "subscriptions out of shape" | "no has_more" | "more pages";
+let mode: Mode = "healthy";
+
+globalThis.fetch = (async (input: string | URL | Request, init?: RequestInit) => {
+  const url = new URL(String(input));
+  const json = (v: unknown, status = 200) => new Response(JSON.stringify(v), { status });
+  if (url.hostname === "api.resend.com") return json({ id: "synthetic_email" });
+  if (url.hostname !== "api.stripe.com") throw new Error(`unexpected request to ${url.hostname}`);
+  const path = url.pathname.replace(/^\/v1/, "");
+  const method = init?.method ?? "GET";
+  if (method === "GET" && path === "/customers") {
+    if (mode === "customers out of shape") return json({ object: "list" });
+    return json({ object: "list", data: url.searchParams.get("email") === "member@example.com" ? [{ id: "cus_member0001" }] : [], has_more: false });
+  }
+  if (method === "GET" && path === "/subscriptions") {
+    if (mode === "subscriptions out of shape") return json({ object: "list", data: "unreadable", has_more: false });
+    if (mode === "no has_more") return json({ object: "list", data: subs });
+    // 20 of another store's on this page; the member's own would be on the next one.
+    if (mode === "more pages") return json({ object: "list", data: Array.from({ length: 20 }, (_, i) => subscription(`sub_other${String(i).padStart(5, "0")}`, { metadata: { store: "another", product: "x" } })), has_more: true });
+    return json({ object: "list", data: subs, has_more: false });
+  }
+  if (method === "GET" && path.startsWith("/products")) return json({ object: "list", data: [], has_more: false });
+  if (method === "POST" && path.startsWith("/subscriptions/")) {
+    const body = new URLSearchParams(String(init?.body ?? ""));
+    const sub = subs.find((s) => s.id === path.split("/")[2]);
+    if (!sub) return json({ error: { code: "resource_missing", message: "No such subscription." } }, 404);
+    // As Stripe applies it: the trial ends at trial_end, and metadata is merged, an empty value removing its key.
+    sub.status = "trialing";
+    sub.trial_end = Number(body.get("trial_end"));
+    for (const [key, value] of body) {
+      const name = /^metadata\[(.+)\]$/.exec(key)?.[1];
+      if (!name) continue;
+      if (value === "") delete sub.metadata[name];
+      else sub.metadata[name] = value;
+    }
+    return json(sub);
+  }
+  return json({ object: "list", data: [], has_more: false });
+}) as typeof fetch;
+
+/** The membership as Stripe holds it after the free days ended and the next charge was paid: running, its trial_end kept. */
+const renewed = (sub: Sub): Sub => ({ ...structuredClone(sub), status: "active" });
+
+async function main(): Promise<void> {
+  redis.clear();
+  const owner = "paid-free-days@example.com";
+  await claimHandle(owner, "paiddays", "Paid Days", "");
+  await ensureStatsId(owner);
+  await ensureStoreId(owner);
+  await setStripeAccount(owner, "acct_1Paiddaysxxxxxx", true);
+  const store = (await storeForEmail(owner))!;
+  const by = { who: owner, role: "owner" as const };
+
+  part("A paying member given free days is still a paying member");
+  subs = [subscription("sub_paid000001")];
+  const before = readSub(structuredClone(subs[0]) as never, HANDLES)!;
+  const n0 = numbersFrom([before], "usd", NOW);
+  const m0 = movementsFrom([before], new Map(), "usd", NOW);
+  is("control, before: paying, at $29 a month, nobody in a trial", [n0.paying, n0.mrr, n0.trialing], [1, 2900, 0]);
+  const given = await giveFreeDays(store, "member@example.com", "sub_paid000001", 7, PERIOD_END, by, NOW);
+  is("the free days are given", given.ok, true);
+  is("Stripe now says trialing, to the next charge plus the days", [subs[0].status, subs[0].trial_end], ["trialing", PERIOD_END + 7 * DAY]);
+  const during = readSub(structuredClone(subs[0]) as never, HANDLES)!;
+  const n1 = numbersFrom([during], "usd", NOW);
+  is("while the days run: still counted paying, MRR whole, nobody in a free trial", [n1.paying, n1.mrr, n1.trialing], [1, 2900, 0]);
+  is("while the days run: their product row says the same", n1.byProduct.map((p) => [p.members, p.trialing, p.mrr]), [[1, 0, 2900]]);
+  const m1 = movementsFrom([during], new Map(), "usd", NOW);
+  is("while the days run: the months they paid are not erased", [m1.months.length, m1.months.at(-1)?.end], [m0.months.length, m0.months.at(-1)?.end]);
+  is("while the days run: the same months, the same MRR each", m1.months.map((m) => m.end), m0.months.map((m) => m.end));
+
+  const later = PERIOD_END + 9 * DAY;
+  const after = readSub(renewed(subs[0]) as never, HANDLES)!;
+  const n2 = numbersFrom([after], "usd", later);
+  is("after the days end and the next charge is paid: no trial ended, none converted", [n2.trialsEnded, n2.trialsConverted], [0, 0]);
+  is("after: paying, MRR whole", [n2.paying, n2.mrr], [1, 2900]);
+
+  part("Given again while they run: still paid");
+  const again = await giveFreeDays(store, "member@example.com", "sub_paid000001", 3, PERIOD_END + 7 * DAY, by, NOW);
+  is("more days are given", again.ok, true);
+  const n3 = numbersFrom([readSub(structuredClone(subs[0]) as never, HANDLES)!], "usd", NOW);
+  is("still counted paying, nobody in a free trial", [n3.paying, n3.trialing], [1, 0]);
+
+  part("An earlier real trial on the same membership is still one");
+  const trialEnded = NOW - 30 * DAY;
+  subs = [subscription("sub_trialed0001", { start_date: NOW - 44 * DAY, trial_end: trialEnded })];
+  const t0 = numbersFrom([readSub(structuredClone(subs[0]) as never, HANDLES)!], "usd", NOW);
+  is("control, before: the trial that ended 30 days ago converted", [t0.trialsEnded, t0.trialsConverted], [1, 1]);
+  is("free days are given on it", (await giveFreeDays(store, "member@example.com", "sub_trialed0001", 7, PERIOD_END, by, NOW)).ok, true);
+  const t1 = numbersFrom([readSub(structuredClone(subs[0]) as never, HANDLES)!], "usd", NOW);
+  is("while the days run: that trial still ended and converted, and the member is paying", [t1.trialsEnded, t1.trialsConverted, t1.paying, t1.trialing], [1, 1, 1, 0]);
+  // Seventy days on, the real trial is more than 90 days back: only the free days could still be counted, and they never are.
+  const t2 = numbersFrom([readSub(renewed(subs[0]) as never, HANDLES)!], "usd", PERIOD_END + 50 * DAY);
+  is("after: the free days are never a second trial", [t2.trialsEnded, t2.trialsConverted, t2.paying], [0, 0, 1]);
+
+  part("Free days inside a real trial leave it a trial");
+  subs = [subscription("sub_trial00001", { status: "trialing", start_date: NOW - 2 * DAY, trial_end: TRIAL_END })];
+  is("free days are given on a trial", (await giveFreeDays(store, "member@example.com", "sub_trial00001", 3, TRIAL_END, by, NOW)).ok, true);
+  const r1 = numbersFrom([readSub(structuredClone(subs[0]) as never, HANDLES)!], "usd", NOW);
+  is("never paid: still in a free trial, not paying", [r1.paying, r1.trialing, r1.mrr], [0, 1, 0]);
+
+  part("The yearly offer");
+  const club = { id: "prod000001", priceCents: 2900, recurring: { interval: "month", trialDays: 0, payments: 0 }, options: [], pwyw: null, yearly: { cents: 29000 } };
+  subs = [subscription("sub_yearly0001")];
+  is("control: a paying monthly member is offered yearly", yearlyChoice(structuredClone(subs[0]) as never, club as never, [], "usd", NOW)?.cents, 29000);
+  is("control: a member in a real trial is offered yearly", yearlyChoice(subscription("sub_trial00002", { status: "trialing", trial_end: TRIAL_END }) as never, club as never, [], "usd", NOW)?.cents, 29000);
+  await giveFreeDays(store, "member@example.com", "sub_yearly0001", 7, PERIOD_END, by, NOW);
+  is("while paid free days run: not offered (Stripe would charge nothing for the switch)", yearlyChoice(structuredClone(subs[0]) as never, club as never, [], "usd", NOW), null);
+  is("after they end: the email that offers it counts the payments from the real start", askFits(renewed(subs[0]) as never, PERIOD_END + 9 * DAY), true);
+  is("control: a real trial that ended a week ago is too recent for the email", askFits(subscription("sub_trial00003", { start_date: NOW - 21 * DAY, trial_end: NOW - 7 * DAY }) as never, NOW), false);
+
+  part("An answer from Stripe that cannot be read is not 'no membership' (rule 24)");
+  subs = [subscription("sub_live000001")];
+  mode = "healthy";
+  is("control: the member's running membership is found", (await freeDaysSubs(store, "member@example.com", NOW))?.map((s) => s.id), ["sub_live000001"]);
+  for (const m of ["customers out of shape", "subscriptions out of shape", "no has_more", "more pages"] as const) {
+    mode = m;
+    is(`${m}: not known, never "has no running membership"`, await freeDaysSubs(store, "member@example.com", NOW), null);
+    is(`${m}: giving says Stripe could not be read, never "not a membership of this member"`, await giveFreeDays(store, "member@example.com", "sub_live000001", 7, PERIOD_END, by, NOW), { ok: false, reason: "stripe" });
+  }
+  mode = "healthy";
+  is("control: an address with no customer is a confirmed none", await freeDaysSubs(store, "nobody@example.com", NOW), []);
+
+  done();
+}
+
+main().catch((error) => {
+  console.error(error);
+  process.exit(1);
+});
diff --git a/tests/member-free-days-switch.test.ts b/tests/member-free-days-switch.test.ts
new file mode 100644
index 000000000..7906df996
--- /dev/null
+++ b/tests/member-free-days-switch.test.ts
@@ -0,0 +1,131 @@
+/**
+ * 641 [WG1], second look (Claude 4 team review of #2912, A1; fixed by Claude 4
+ * on Claude 5's behalf; fixture from the review's proof, itself from
+ * tests/cx1-review-2764-invoice.test.ts). A member who PAID and was given free
+ * days reads "trialing" on Stripe. Stripe prorates nothing inside a trial, so
+ * a tier switch made then would put the dearer tier on for free until the
+ * free days end, and the old code also told the member "You are in your free
+ * trial". While a paid member's free days run, a switch of tier or to yearly
+ * is refused, with words that say why, and nothing is sent to Stripe; a real
+ * free trial still switches as before.
+ *
+ * Synthetic transport only; no request leaves the process.
+ */
+import { addProduct, claimHandle, ensureStatsId, ensureStoreId, setProductLink, setStoreTiers, setStripeAccount, setSubscription, storeForEmail } from "@/lib/store";
+import { requestManageLink } from "@/lib/membership-manage";
+import { previewSwitch, switchTier } from "@/lib/tier-switch";
+import { previewYearly, switchYearly } from "@/lib/yearly-switch";
+import { giveFreeDays } from "@/lib/member-free-days";
+import { membershipWords } from "@/lib/buyer-words/membership";
+import { EU_WITHDRAWAL_CONSENT_VERSION } from "@/lib/digital-consent";
+import { store as redis } from "./redis-stub";
+import { paidPeriod } from "./billing-period-fixture";
+import { done, is, part } from "./check";
+
+const emails: { to: string | string[]; text: string }[] = [];
+const subscription = "sub_CX1Member0001", customer = "cus_CX1Member0001";
+const DAY = 86_400;
+const now = Math.floor(Date.now() / 1000);
+const PERIOD_END = now + 20 * DAY;
+const consent = { version: EU_WITHDRAWAL_CONSENT_VERSION, at: now };
+let product = "";
+let chargeRequests = 0;
+const why = (result: { ok: boolean }) => ("reason" in result ? String((result as { reason: unknown }).reason) : "ok");
+// The subscription as Stripe holds it, changed only by what is posted to it.
+const state: { status: string; trial_end: number | null; metadata: Record<string, string> } = { status: "active", trial_end: null, metadata: {} };
+const row = () => ({
+  id: subscription, object: "subscription", status: state.status, customer, created: now - 90 * DAY,
+  start_date: now - 90 * DAY, trial_end: state.trial_end, discount: null, discounts: [], pause_collection: null,
+  metadata: { store: "cx1switch", product, ...state.metadata },
+  items: { data: [{ id: "si_CX1Member0001", quantity: 1, current_period_end: PERIOD_END, price: { id: "price_CX1Monthly0001", unit_amount: 2000, currency: "usd", metadata: { product }, recurring: { interval: "month", interval_count: 1 } } }] },
+});
+globalThis.fetch = (async (input: string | URL | Request, init?: RequestInit) => {
+  const url = new URL(String(input)), method = init?.method ?? "GET";
+  const json = (value: unknown) => new Response(JSON.stringify(value));
+  if (url.hostname === "api.resend.com") { emails.push(JSON.parse(String(init?.body))); return json({ id: "synthetic_email" }); }
+  if (url.hostname !== "api.stripe.com") throw new Error("Unexpected external request");
+  const path = url.pathname.replace(/^\/v1/, ""), body = new URLSearchParams(String(init?.body ?? ""));
+  if (method === "GET" && path === "/customers") return json({ object: "list", data: [{ id: customer, created: 1 }], has_more: false });
+  if (method === "GET" && path === `/customers/${customer}`) return json({ id: customer, email: "member@example.test" });
+  if (method === "GET" && path === "/subscriptions") return json({ object: "list", data: [row()], has_more: false });
+  if (method === "GET" && path.startsWith("/products")) return json({ object: "list", data: [], has_more: false });
+  if (method === "POST" && path === "/prices") return json({ id: "price_CX1Target0001" });
+  if (method === "POST" && path === "/invoices/create_preview") return json({ currency: "usd", starting_balance: 0, lines: { object: "list", has_more: false, data: [{ amount: 667, proration: true, period: { start: Number(body.get("subscription_details[proration_date]")) } }] } });
+  if (method === "POST" && path === `/subscriptions/${subscription}`) {
+    if (body.has("trial_end")) {
+      // Free days, as Stripe applies them: trialing to trial_end, metadata merged, an empty value removing its key.
+      state.status = "trialing";
+      state.trial_end = Number(body.get("trial_end"));
+      for (const [key, value] of body) {
+        const name = /^metadata\[(.+)\]$/.exec(key)?.[1];
+        if (!name) continue;
+        if (value === "") delete state.metadata[name];
+        else state.metadata[name] = value;
+      }
+      return json(row());
+    }
+    if (!body.has("items[0][price]")) return json(row());
+    chargeRequests++;
+    return json({ ...row(), pending_update: null, items: { data: [{ id: "si_CX1Member0001", price: { id: body.get("items[0][price]") } }] }, metadata: { ...row().metadata, ...(body.get("metadata[dc]") ? { dc: body.get("metadata[dc]") } : {}) }, latest_invoice: { id: "in_CX1Paid0001", status: "paid", total: 667, amount_paid: 667, currency: "usd" } });
+  }
+  throw new Error(`Missing synthetic response ${method} ${path}`);
+}) as typeof fetch;
+
+async function main() {
+  redis.clear();
+  process.env.STRIPE_SECRET_KEY = "sk_test_free_days_switch_synthetic_only";
+  process.env.RESEND_API_KEY = "re_test_tiers_only";
+  const owner = "free-days-switch-owner@example.test";
+  await claimHandle(owner, "cx1switch", "Synthetic membership", "");
+  await ensureStatsId(owner);
+  await ensureStoreId(owner);
+  await setStripeAccount(owner, "acct_1CX1Fake0001", true);
+  await setSubscription(owner, { customerId: "cus_CX1Owner0001", subscriptionId: "sub_CX1Owner0001", active: true, period: paidPeriod() });
+  const monthly = { interval: "month" as const, trialDays: 0, payments: 0 };
+  const a = await addProduct(owner, "Basic", "", "20", monthly), b = await addProduct(owner, "Pro", "", "30", monthly);
+  if (!a.ok || !b.ok) throw new Error("Missing products");
+  product = a.product.id;
+  await setProductLink(owner, product, "https://example.test/basic");
+  await setProductLink(owner, b.product.id, "https://example.test/pro");
+  await setStoreTiers(owner, [product, b.product.id]);
+  const store = (await storeForEmail(owner))!;
+  const sent = await requestManageLink({ store, email: "member@example.test", ip: "203.0.113.15", origin: "https://example.test" });
+  const token = /token=([0-9a-f]{64})/.exec(String(emails.at(-1)?.text ?? ""))?.[1];
+  if (sent !== "sent" || !token) throw new Error("no token");
+
+  part("Control: a paying member with no free days");
+  const control = await previewSwitch(store, token, subscription, b.product.id);
+  is("the upgrade shows Stripe's prorated amount due", control.ok ? [control.preview.trialing, control.preview.due] : control, [false, 667]);
+
+  part("A paying member given free days");
+  const given = await giveFreeDays(store, "member@example.test", subscription, 7, PERIOD_END, { who: owner, role: "owner" }, now);
+  is("the free days are given", given.ok, true);
+  is("Stripe now says trialing", state.status, "trialing");
+  const preview = await previewSwitch(store, token, subscription, b.product.id);
+  is("the switch page refuses while the free days run, and says why (never $0, never 'free trial')", preview, { ok: false, reason: "freeDays" });
+  emails.length = 0;
+  const switched = await switchTier(store, token, subscription, b.product.id, now, consent);
+  is("the switch itself is refused the same way", switched, { ok: false, reason: "freeDays" });
+  is("nothing was sent to Stripe to switch", chargeRequests, 0);
+  is("no receipt says 'You are in your free trial'", emails.some((e) => String(e.text).includes("free trial")), false);
+  is("moving to yearly is refused the same way", [why(await previewYearly(store, token, subscription)), why(await switchYearly(store, token, subscription, now, consent))], ["freeDays", "freeDays"]);
+  is("nothing was sent to Stripe for yearly either", chargeRequests, 0);
+  const languages = ["en", "es", "fr", "de", "it", "nl", "pt"] as const;
+  is(
+    "the words say so in every language, on the switch page and back on the membership page",
+    languages.every((l) => (membershipWords(l).switchProblems.freeDays?.body.length ?? 0) > 40 && (membershipWords(l).manageNotices["free-days"]?.title.length ?? 0) > 10),
+    true,
+  );
+
+  part("Control: a real free trial still switches as before");
+  state.status = "trialing";
+  state.trial_end = now + 5 * DAY;
+  state.metadata = {};
+  const trial = await previewSwitch(store, token, subscription, b.product.id);
+  is("in a real trial the switch is offered, nothing to pay now", trial.ok ? [trial.preview.trialing, trial.preview.due] : trial, [true, 0]);
+  is("free days given inside a real trial leave it a trial", (await giveFreeDays(store, "member@example.test", subscription, 3, now + 5 * DAY, { who: owner, role: "owner" }, now)).ok, true);
+  const trial2 = await previewSwitch(store, token, subscription, b.product.id);
+  is("so the switch is still offered as a trial's", trial2.ok ? trial2.preview.trialing : trial2, true);
+  done();
+}
+main().catch((error) => { console.error(error); process.exit(1); });
diff --git a/tests/member-free-days.test.ts b/tests/member-free-days.test.ts
new file mode 100644
index 000000000..03eb8120d
--- /dev/null
+++ b/tests/member-free-days.test.ts
@@ -0,0 +1,245 @@
+/**
+ * 641 [WG1]: free days given to one member (lib/member-free-days.ts), with
+ * Stripe and the email sender faked through fetch and Redis in memory. What is
+ * checked:
+ *
+ *   - the next charge moves exactly the days given, by the subscription's
+ *     trial_end with no proration, on the creator's own Stripe account;
+ *   - only this store's running memberships of that address, and not one set
+ *     to end, paused or behind on a payment;
+ *   - an answer from Stripe or Redis that cannot be read records nothing as
+ *     done: no log line, no email;
+ *   - two presses at once move the date once and email once;
+ *   - who gave it, when and how many days is in the store's activity log;
+ *   - the member's email is counted in the store's emails and written in the
+ *     store's language, in every language a membership speaks;
+ *   - only a role that may touch payments sees it, and the route refuses the
+ *     others.
+ */
+import { readFileSync } from "node:fs";
+import { NextRequest } from "next/server";
+import { SESSION_COOKIE, openSession } from "@/lib/auth";
+import { claimHandle, ensureStatsId, ensureStoreId, setLanguage, setStripeAccount, storeForEmail } from "@/lib/store";
+import { putMember, readLog } from "@/lib/team";
+import { can } from "@/lib/team-roles";
+import { memberSubs } from "@/lib/member-discount";
+import { FREE_DAYS_MAX, freeDaysState, movedCharge, parseFreeDays } from "@/lib/member-free-days-rules";
+import { freeDaysSubs, giveFreeDays } from "@/lib/member-free-days";
+import { FREE_DAYS_WORDS } from "@/lib/buyer-words/free-days";
+import { MEMBERSHIP_WORDS } from "@/lib/buyer-words/membership";
+import { speechFor } from "@/lib/buyer-words";
+import { allowanceUsed } from "@/lib/store-allowance";
+import { POST } from "@/app/api/store/member-free-days/route";
+import { store as redis } from "./redis-stub";
+import { done, is, part } from "./check";
+
+process.env.STRIPE_SECRET_KEY = "sk_test_member_free_days_only";
+// One of the synthetic sender keys tests/resend-fixture-credentials.ts knows: never a live one.
+process.env.RESEND_API_KEY = "re_test_a_stand_in_key_for_tests_only";
+
+const DAY = 86_400;
+const NOW = Math.floor(Date.now() / 1000);
+const PERIOD_END = NOW + 20 * DAY;
+const TRIAL_END = NOW + 5 * DAY;
+
+const subscription = (id: string, extra: Record<string, unknown> = {}): Record<string, unknown> => ({
+  id,
+  status: "active",
+  metadata: { store: "daysstore", product: "prod000001" },
+  items: { data: [{ current_period_end: PERIOD_END, price: { unit_amount: 2900, currency: "usd", recurring: { interval: "month" } } }] },
+  ...extra,
+});
+const subs: Record<string, unknown>[] = [
+  subscription("sub_live000001"),
+  subscription("sub_trial00001", { status: "trialing", trial_end: TRIAL_END }),
+  subscription("sub_ending0001", { cancel_at_period_end: true }),
+  subscription("sub_paused0001", { pause_collection: { behavior: "void", resumes_at: PERIOD_END + 30 * DAY } }),
+  subscription("sub_behind0001", { status: "past_due" }),
+  subscription("sub_else000001", { metadata: { store: "another" } }),
+  subscription("sub_plan000001", { metadata: { store: "daysstore", kind: "plan" } }),
+];
+const byId = (id: string) => subs.find((s) => s.id === id)!;
+
+type Mode = "ok" | "error" | "odd" | "refuse";
+let mode: Mode = "ok";
+let slow = 0;
+const posted: { path: string; body: URLSearchParams; key: string | null; account: string | null }[] = [];
+const emails: { to: string; subject: string; text: string }[] = [];
+globalThis.fetch = (async (input: string | URL | Request, init?: RequestInit) => {
+  const url = new URL(String(input));
+  const answer = (body: unknown, status = 200) => new Response(JSON.stringify(body), { status });
+  if (url.hostname === "api.resend.com") {
+    const body = JSON.parse(String(init?.body ?? "{}")) as { to?: string | string[]; subject?: string; text?: string };
+    if (init?.method === "POST" && url.pathname === "/emails") emails.push({ to: String([body.to].flat()[0]), subject: body.subject ?? "", text: body.text ?? "" });
+    return answer({ id: `email_${emails.length}` });
+  }
+  const path = url.pathname.replace(/^\/v1/, "");
+  // Stripe's lists carry has_more: an answer without it is not one this code reads (rule 24).
+  if (path === "/customers") return answer({ object: "list", data: url.searchParams.get("email") === "member@example.com" ? [{ id: "cus_member0001" }] : [], has_more: false });
+  if (path === "/subscriptions" && (init?.method ?? "GET") === "GET") return answer({ object: "list", data: url.searchParams.get("customer") === "cus_member0001" ? subs : [], has_more: false });
+  if (path.startsWith("/products")) return answer({ object: "list", data: [] });
+  if (init?.method === "POST" && path.startsWith("/subscriptions/")) {
+    const headers = new Headers(init.headers);
+    const body = new URLSearchParams(String(init.body));
+    posted.push({ path, body, key: headers.get("Idempotency-Key"), account: headers.get("Stripe-Account") });
+    if (slow) await new Promise((resolve) => setTimeout(resolve, slow));
+    if (mode === "error") return answer({ error: { message: "Something went wrong on Stripe's end." } }, 500);
+    if (mode === "refuse") return answer({ error: { code: "resource_missing", message: "No such subscription." } }, 400);
+    const sub = byId(path.split("/")[2]);
+    if (mode === "odd") return answer({ id: sub.id });
+    const end = Number(body.get("trial_end"));
+    Object.assign(sub, { status: "trialing", trial_end: end });
+    // Metadata merged as Stripe merges it: an empty value removes its key.
+    const meta = { ...(sub.metadata as Record<string, string>) };
+    for (const [key, value] of body) {
+      const name = /^metadata\[(.+)\]$/.exec(key)?.[1];
+      if (!name) continue;
+      if (value === "") delete meta[name];
+      else meta[name] = value;
+    }
+    sub.metadata = meta;
+    return answer(sub);
+  }
+  return answer({ object: "list", data: [] });
+}) as typeof fetch;
+
+async function main(): Promise<void> {
+  redis.clear();
+  const owner = "member-free-days@example.com";
+  await claimHandle(owner, "daysstore", "Days Store", "");
+  await ensureStatsId(owner);
+  await ensureStoreId(owner);
+  await setStripeAccount(owner, "acct_1Freedaysxxxxxx", true);
+  await setLanguage(owner, "es");
+  const store = (await storeForEmail(owner))!;
+  const by = { who: owner, role: "owner" as const };
+
+  part("The days");
+  is("a whole number from 1 to the cap, and nothing else", [0, 1, FREE_DAYS_MAX, FREE_DAYS_MAX + 1, "14", 1.5, -3, "x", null].map(parseFreeDays), [null, 1, FREE_DAYS_MAX, null, 14, null, null, null, null]);
+  is("the cap is 90 days", FREE_DAYS_MAX, 90);
+  is("the next charge moves exactly the days given", movedCharge(PERIOD_END, 14), PERIOD_END + 14 * DAY);
+  is(
+    "a running membership's next charge, and why another has none to move",
+    [byId("sub_live000001"), byId("sub_trial00001"), byId("sub_ending0001"), byId("sub_paused0001"), byId("sub_behind0001")].map((s) => freeDaysState(s, NOW)),
+    [
+      { nextCharge: PERIOD_END, blocked: null },
+      { nextCharge: TRIAL_END, blocked: null },
+      { nextCharge: PERIOD_END, blocked: "ending" },
+      { nextCharge: PERIOD_END, blocked: "paused" },
+      { nextCharge: 0, blocked: "behind" },
+    ],
+  );
+  is("a membership on a schedule of changes is left alone", freeDaysState(subscription("sub_sched00001", { schedule: "sub_sched_1" }), NOW).blocked, "scheduled");
+
+  part("What the studio is shown");
+  const found = await freeDaysSubs(store, "member@example.com");
+  is(
+    "only this store's running memberships of that address, each with its next charge",
+    found?.map((s) => [s.id, s.nextCharge, s.blocked]),
+    [
+      ["sub_live000001", PERIOD_END, null],
+      ["sub_trial00001", TRIAL_END, null],
+      ["sub_ending0001", PERIOD_END, "ending"],
+      ["sub_paused0001", PERIOD_END, "paused"],
+      ["sub_behind0001", 0, "behind"],
+    ],
+  );
+  is("the discount's own reading still reads the same memberships (healthy control)", (await memberSubs(store, "member@example.com"))?.map((s) => s.id), ["sub_live000001", "sub_trial00001", "sub_ending0001", "sub_paused0001", "sub_behind0001"]);
+
+  part("Refused before Stripe is asked");
+  is("another store's membership", await giveFreeDays(store, "member@example.com", "sub_else000001", 7, PERIOD_END, by), { ok: false, reason: "not_member" });
+  is("a payment plan", await giveFreeDays(store, "member@example.com", "sub_plan000001", 7, PERIOD_END, by), { ok: false, reason: "not_member" });
+  is("one set to end", await giveFreeDays(store, "member@example.com", "sub_ending0001", 7, PERIOD_END, by), { ok: false, reason: "blocked", blocked: "ending" });
+  is("one behind on a payment", await giveFreeDays(store, "member@example.com", "sub_behind0001", 7, 0, by), { ok: false, reason: "blocked", blocked: "behind" });
+  is("no days, or more than the cap", [(await giveFreeDays(store, "member@example.com", "sub_live000001", 0, PERIOD_END, by)).ok, (await giveFreeDays(store, "member@example.com", "sub_live000001", 91, PERIOD_END, by)).ok], [false, false]);
+  is("a next charge that is not the one the creator saw", await giveFreeDays(store, "member@example.com", "sub_live000001", 7, PERIOD_END - DAY, by), { ok: false, reason: "changed" });
+  is("nothing was sent to Stripe for any of them", posted.length, 0);
+
+  part("An answer that cannot be read records nothing as done");
+  mode = "error";
+  is("Stripe failing: unknown", await giveFreeDays(store, "member@example.com", "sub_live000001", 14, PERIOD_END, by), { ok: false, reason: "unknown" });
+  mode = "odd";
+  is("Stripe answering without the date asked for: unknown", await giveFreeDays(store, "member@example.com", "sub_live000001", 14, PERIOD_END, by), { ok: false, reason: "unknown" });
+  const realPipeline = redis.pipeline.bind(redis);
+  redis.pipeline = (async (commands: (string | number)[][]) => (commands[0]?.[0] === "SET" ? [{ odd: true }] : realPipeline(commands))) as typeof redis.pipeline;
+  mode = "ok";
+  const before = posted.length;
+  is("Redis answering the claim in an unknown shape: unknown", await giveFreeDays(store, "member@example.com", "sub_live000001", 14, PERIOD_END, by), { ok: false, reason: "unknown" });
+  redis.pipeline = realPipeline;
+  is("and Stripe was not asked then", posted.length, before);
+  is("no log line and no email for any of them", [(await readLog(store.sid)).length, emails.length], [0, 0]);
+  mode = "refuse";
+  is("Stripe saying no: refused, nothing changed", await giveFreeDays(store, "member@example.com", "sub_live000001", 14, PERIOD_END, by), { ok: false, reason: "refused" });
+  is("the membership still has its date", byId("sub_live000001").trial_end, undefined);
+
+  part("Giving the days");
+  mode = "ok";
+  const emailsUsed = await allowanceUsed(store, "email");
+  const given = await giveFreeDays(store, "member@example.com", "sub_live000001", 14, PERIOD_END, by);
+  is("given, with the new next charge", given, { ok: true, nextCharge: PERIOD_END + 14 * DAY, emailed: true });
+  const last = posted.at(-1)!;
+  is(
+    "on the creator's account, by trial_end with no proration, with an idempotency key",
+    [last.path, last.account, last.body.get("trial_end"), last.body.get("proration_behavior"), last.key],
+    ["/subscriptions/sub_live000001", "acct_1Freedaysxxxxxx", String(PERIOD_END + 14 * DAY), "none", `member-free-days:sub_live000001:${PERIOD_END}:14`],
+  );
+  is("the membership's next charge on Stripe moved exactly 14 days", byId("sub_live000001").trial_end, PERIOD_END + 14 * DAY);
+  const log = await readLog(store.sid);
+  is("who gave it, when and how many days is in the activity log", [log.length, log[0]?.who, log[0]?.what.includes("14 free days"), typeof log[0]?.at === "string"], [1, owner, true, true]);
+  is("the member is emailed once", [emails.length, emails[0]?.to], [1, "member@example.com"]);
+  is("and the email was taken from the store's own emails first", (await allowanceUsed(store, "email")) - emailsUsed, 1);
+  const es = FREE_DAYS_WORDS.es;
+  const date = speechFor("es", "usd").date((PERIOD_END + 14 * DAY) * 1000);
+  is("in the store's language, with the new date", [emails[0]?.subject === es.subject("Days Store"), emails[0]?.text.includes(date), emails[0]?.text.includes(es.days(14))], [true, true, true]);
+  is("pressing again with the date seen before: the date already moved, nothing more", await giveFreeDays(store, "member@example.com", "sub_live000001", 14, PERIOD_END, by), { ok: false, reason: "changed" });
+
+  part("Two presses at once");
+  const postedBefore = posted.length;
+  const emailsBefore = emails.length;
+  slow = 30;
+  const both = await Promise.all([
+    giveFreeDays(store, "member@example.com", "sub_trial00001", 10, TRIAL_END, by),
+    giveFreeDays(store, "member@example.com", "sub_trial00001", 10, TRIAL_END, by),
+  ]);
+  slow = 0;
+  is("one gives the days, the other is told it is under way", both.map((r) => (r.ok ? "ok" : r.reason)).sort(), ["busy", "ok"]);
+  is("Stripe asked once, the member emailed once", [posted.length - postedBefore, emails.length - emailsBefore], [1, 1]);
+  is("a trial's end moved exactly the days given", byId("sub_trial00001").trial_end, TRIAL_END + 10 * DAY);
+
+  part("The member's words");
+  const languages = Object.keys(MEMBERSHIP_WORDS).sort();
+  is("in every language a membership speaks", Object.keys(FREE_DAYS_WORDS).sort(), languages);
+  is("each its own, not English again", languages.filter((code) => code !== "en" && FREE_DAYS_WORDS[code as keyof typeof FREE_DAYS_WORDS].subject("X") === FREE_DAYS_WORDS.en.subject("X")), []);
+  is("one day and many", [FREE_DAYS_WORDS.en.days(1), FREE_DAYS_WORDS.en.days(14)], ["1 free day", "14 free days"]);
+
+  part("Who may give them");
+  is("only a role that may touch payments", [can("owner", "payments"), can("admin", "payments"), can("editor", "payments"), can("support", "payments")], [true, false, false, false]);
+  const page = readFileSync("app/studio/memberships/page.tsx", "utf8");
+  is("the studio draws it only for that role", /can\(access\.role, "payments"\) \? \(\s*<section aria-labelledby="member-free-days-title"/.test(page) && page.includes("<MemberFreeDays"), true);
+  const admin = "admin-days@example.com";
+  await putMember(store, admin, "admin");
+  const session = await openSession(admin);
+  const postedRoute = posted.length;
+  const response = await POST(
+    new NextRequest(`https://marktmorgen.com/api/store/member-free-days?store=${store.sid}`, {
+      method: "POST",
+      headers: { "content-type": "application/json", cookie: `${SESSION_COOKIE}=${session}`, origin: "https://marktmorgen.com", host: "marktmorgen.com" },
+      body: JSON.stringify({ action: "give", email: "member@example.com", subscription: "sub_live000001", days: 5, expected: PERIOD_END + 14 * DAY }),
+    }),
+  );
+  is("an admin is refused by the route, and Stripe is not asked", [response.status, posted.length - postedRoute], [403, 0]);
+  const route = readFileSync("app/api/store/member-free-days/route.ts", "utf8");
+  is("the route asks for the payments permission", route.includes('guardStoreWrite(request, "payments")'), true);
+
+  part("The studio's form");
+  const component = readFileSync("components/member-free-days.tsx", "utf8");
+  is("a labeled whole number with its bounds and a hint", component.includes('type="number"') && component.includes("min={1}") && component.includes("max={FREE_DAYS_MAX}") && component.includes("aria-describedby"), true);
+  is("a review step that shows the new date before anything changes", component.includes("Review") && component.includes("movedCharge(") && component.includes("Go back"), true);
+  is("the result announced and errors said", component.includes('role="status"') && component.includes('role="alert"'), true);
+  done();
+}
+
+main().catch((error) => {
+  console.error(error);
+  process.exit(1);
+});
